from scapy.all import PcapReader,IP,TCP,UDP
from collections import Counter,defaultdict
pairs=Counter(); srcports=defaultdict(set)
with PcapReader('/root/packets.pcap') as p:
  for pkt in p:
    if pkt.haslayer(IP) and pkt.haslayer(TCP):
      ip=pkt[IP]
      pairs[(ip.src,ip.dst)] += 1
      srcports[(ip.src,ip.dst)].add(int(pkt[TCP].dport))
for k,v in pairs.most_common(10):
  print(k,v,'ports',len(srcports[k]))
